import{_ as e,o as i,c as s,a5 as r}from"./chunks/framework.CsGesDJn.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"feature/authentication/3-2-1-sign-up/report3_spec.md","filePath":"feature/authentication/3-2-1-sign-up/report3_spec.md"}'),o={name:"feature/authentication/3-2-1-sign-up/report3_spec.md"};function n(a,t,l,u,g,d){return i(),s("div",null,[...t[0]||(t[0]=[r("<p><strong>3.2.1 Sign Up (Email + OTP Verification)</strong></p><p><strong>Function Trigger</strong></p><p>Begins when an unauthenticated Guest visits /register or /verify-otp after submitting the registration form.</p><p><strong>Function Description</strong></p><ul><li><strong>Actors / Roles</strong>: GUEST. Creates a new user account with default role USER.</li><li><strong>Purpose</strong>: Register a new account, verify email ownership via a one-time code, and hand the user to Sign In.</li><li><strong>Interface</strong>: Registration form with Full Name, Email, Password, Confirm Password; OTP Verification screen with a 6-digit code input and a Resend link.</li><li><strong>Data Processing</strong>: business-service validates email format and password policy, checks database uniqueness (BR-01), hashes password via BCrypt cost=12 (BR-02), creates user record, generates a 6-digit OTP with 10-minute expiry (BR-03), and dispatches the OTP email.</li></ul><p><strong>Screen Layout</strong></p><p>Figure — Registration Screen:</p><ul><li>Center: Text input for Full Name, Text input for Email, Password input with strength indicator, Confirm Password input.</li><li>Buttons: Primary button &quot;Create Account&quot;; Divider &quot;or&quot;; Button &quot;Sign up with Google&quot;.</li><li>Footer: Text link &quot;Already have an account? Log in&quot;.</li></ul><p>Figure — OTP Verification Screen:</p><ul><li>Center: 6 single-digit inputs for the OTP code, Verify button, Resend link with cooldown countdown.</li></ul><p><strong>Function Details</strong></p><ul><li><p><strong>Data Specifications</strong></p><ul><li><strong>Input required (register)</strong>: email, password, fullName.</li><li><strong>Input required (verify-otp)</strong>: email, otpCode.</li><li><strong>Input optional</strong>: confirmPassword (client-side check only, never sent to the server).</li><li><strong>System data</strong>: userId (UUID), defaultRole (USER), status (ACTIVE), otpCode, otpExpiry, createdAt (timestamp).</li><li><strong>Output (register)</strong>: userId.</li><li><strong>Output (verify-otp)</strong>: no payload body.</li></ul></li><li><p><strong>Business Rules</strong></p><ul><li><strong>BR-01</strong>: Email is unique, case-insensitive. Duplicate -&gt; 409 EMAIL_ALREADY_EXISTS.</li><li><strong>BR-02</strong>: Password policy: minimum 8 characters + at least 1 digit; hashed with BCrypt cost=12; password is never logged or returned.</li><li><strong>BR-03</strong>: OTP is 6 digits, TTL 10 minutes, single-use; cleared after 5 failed attempts.</li><li><strong>BR-04</strong>: Resend OTP has a 60-second cooldown per email.</li></ul></li><li><p><strong>Validation</strong></p><ul><li>Empty required fields -&gt; Display: <strong>MSG02</strong></li><li>Invalid email format -&gt; Display: <strong>MSG04</strong></li><li>Password does not meet policy -&gt; Display: <strong>MSG05</strong></li><li>Passwords do not match -&gt; Display: <strong>MSG06</strong></li><li>Email already registered -&gt; Display: <strong>MSG08</strong></li><li>OTP wrong or expired -&gt; Display: <strong>MSG20</strong></li></ul></li></ul><p><strong>Functionalities</strong></p><ul><li><p><strong>Normal Flow</strong></p><ol><li>The user navigates to /register and fills in Full Name, Email, Password, and Confirm Password.</li><li>The user clicks &quot;Create Account&quot;.</li><li>The system validates inputs and checks that email is unique in the database.</li><li>The system hashes the password with BCrypt cost=12 and creates a new user record.</li><li>The system generates a 6-digit OTP with a 10-minute expiry and sends it by email.</li><li>The system displays <strong>MSG10</strong> and redirects the user to the OTP Verification screen.</li><li>The user enters the OTP code and clicks Verify.</li><li>The system marks the email verified and redirects the user to Sign In.</li></ol></li><li><p><strong>Abnormal Cases</strong></p><ul><li>3.a1: If the email is already registered, the system displays <strong>MSG08</strong>. 3.a2: The user switches to login or inputs another email.</li><li>3.b1: If password does not meet policy, the system displays <strong>MSG05</strong>. 3.b2: The user enters a valid password.</li><li>7.a1: If the OTP is wrong or expired, the system displays <strong>MSG20</strong>. 7.a2: The user retries or requests Resend.</li></ul></li></ul><p><strong>Post-Conditions</strong></p><ul><li>User record created in users collection with status = ACTIVE and role = USER.</li><li>OTP recorded with a 10-minute expiry until verified.</li><li>Email marked verified after successful OTP check.</li></ul>",16)])])}const m=e(o,[["render",n]]);export{c as __pageData,m as default};
